import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

borrowed_local_pass = verify('borrowed_local_pass', '''
    fn borrow(v: &'a *mut u8) -> &'a *mut u8 {
        return v
    }
    fn main() -> i32 {
        let p = alloc(32)
        let alias: &'a *mut u8 = borrow(p)
        discard alias
        free(p)
        return 0
    }
''', 0)
assert borrowed_local_pass['errors'] == 0, borrowed_local_pass
assert not any('call signature mismatch for `borrow`' in message for message in messages(borrowed_local_pass)), borrowed_local_pass
assert not any('argument 0 type mismatch' in message for message in messages(borrowed_local_pass)), borrowed_local_pass
assert not any('linear value `alias` was not consumed/freed' in message for message in messages(borrowed_local_pass)), borrowed_local_pass

borrow_then_free = verify('borrow_then_free', '''
    fn borrow(v: &'a *mut u8) -> &'a *mut u8 {
        return v
    }
    fn main() -> i32 {
        let p = alloc(32)
        let alias: &'a *mut u8 = borrow(p)
        free(p)
        discard alias
        return 0
    }
''', 1)
assert any('consumes owner `p` via `free(p)` while borrowed reference `alias` is still live' in message for message in messages(borrow_then_free)), borrow_then_free
assert not any('call signature mismatch for `borrow`' in message for message in messages(borrow_then_free)), borrow_then_free
assert not any('linear value `alias` was not consumed/freed' in message for message in messages(borrow_then_free)), borrow_then_free

borrow_then_move = verify('borrow_then_move', '''
    fn borrow(v: &'a *mut u8) -> &'a *mut u8 {
        return v
    }
    fn main() -> i32 {
        let p = alloc(32)
        let alias: &'a *mut u8 = borrow(p)
        let y = p
        discard alias
        free(y)
        return 0
    }
''', 1)
assert any('consumes owner `p` via `let y = p` while borrowed reference `alias` is still live' in message for message in messages(borrow_then_move)), borrow_then_move
assert not any('call signature mismatch for `borrow`' in message for message in messages(borrow_then_move)), borrow_then_move
assert not any('linear value `alias` was not consumed/freed' in message for message in messages(borrow_then_move)), borrow_then_move

shared_return_lifetime = verify('shared_return_lifetime', '''
    fn borrow(v: &'b i32) -> &'b i32 {
        return v
    }
    fn relay(a: &'a i32, b: &'b i32) -> &'a i32 {
        return borrow(b)
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
assert any('returns reference expression with mismatched lifetime' in message for message in messages(shared_return_lifetime)), shared_return_lifetime
assert not any('call signature mismatch for `borrow`' in message for message in messages(shared_return_lifetime)), shared_return_lifetime

mutable_shared_alias = verify('mutable_shared_alias', '''
    fn touch(a: &'a mut i32, b: &'a i32) -> i32 {
        return 0
    }
    fn main() -> i32 {
        let x: i32 = 1
        touch(x, x)
        return 0
    }
''', 1)
assert any('aliases mutable and shared borrows for `x`' in message for message in messages(mutable_shared_alias)), mutable_shared_alias
assert not any('call signature mismatch for `touch`' in message for message in messages(mutable_shared_alias)), mutable_shared_alias
assert not any('argument 0 type mismatch' in message or 'argument 1 type mismatch' in message for message in messages(mutable_shared_alias)), mutable_shared_alias

print('compiler-memory-borrow-regions-ok')

